## Code Example
```javascript
import { useWindowDimensions, FlatList } from 'react-native'
import React, { useMemo } from 'react'

export function useNumColumns(breaks = [400, 800, 1200]) {
  const { width } = useWindowDimensions()
  return useMemo(() => {
    if (width < breaks[0]) return 2
    if (width < breaks[1]) return 3
    if (width < breaks[2]) return 4
    return 5
  }, [width, breaks])
}

function Item({ item }) {
  // simple render, assume fixed height for getItemLayout
  return <ProductCard data={item} />
}

export function ProductGrid({ data }) {
  const numColumns = useNumColumns()
  const ITEM_HEIGHT = 180
  const getItemLayout = (_, index) => (
    { length: ITEM_HEIGHT, offset: ITEM_HEIGHT * index, index }
  )

  const renderItem = useCallback(({ item }) => <Item item={item} />, [])

  return (
    <FlatList
      data={data}
      renderItem={renderItem}
      keyExtractor={item => item.id}
      numColumns={numColumns}
      getItemLayout={getItemLayout}
      initialNumToRender={10}
      maxToRenderPerBatch={10}
      windowSize={21}
    />
  )
}
```

